const expected = String($env.N8N_WEBHOOK_SECRET || '').trim();
if (expected) {
  const headers = ($input.first().json || {}).headers || {};
  const got = String(headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '').trim();
  if (got !== expected) throw new Error('Unauthorized: missing or invalid webhook secret');
}
return $input.all();

const body = ($input.first().json || {}).body || {};
const action = String(body.action || '').trim();
const allowed = new Set(['performance']);
const accessToken = String(body.access_token || '').trim();

if (!allowed.has(action)) {
  return [{ json: { ok: false, error: 'Unsupported report action.' } }];
}
if (!accessToken) {
  return [{ json: { ok: false, error: 'Sign in to read the performance report.' } }];
}

// performance is a GET that reads its parameters from the query string — see
// its params() helper. Forwarded that way rather than as a POST body so the
// handler's contract is unchanged by having moved off Vercel.
const query = new URLSearchParams();
for (const [key, value] of Object.entries(body)) {
  if (key === 'action' || key === 'access_token') continue;
  if (value === undefined || value === null || value === '') continue;
  query.set(key, String(value));
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `${$env.AGENT_BASE_URL}/api/agent/${action}?${query.toString()}`,
    headers: { Authorization: `Bearer ${accessToken}` },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    // Several Zernio reads plus the analytics join. Generous, and still well
    // under the browser's own patience.
    timeout: 180000,
  });
  const payload = response?.body && typeof response.body === 'object'
    ? response.body
    : { ok: false, error: `The agent returned ${response?.statusCode || 'an empty response'}.` };
  return [{ json: payload }];
} catch (err) {
  return [{ json: { ok: false, error: `Could not reach the reports agent: ${String(err?.message || err).slice(0, 300)}` } }];
}
